    {
      "poi_id": "p9",
      "kind": "activity",
      "must_do_id": null,
      "note": "A modest temple fee, not a museum ticket, and the silver pavilion is better with fewer crowds."
    },
    {
      "poi_id": "p13",
      "kind": "activity",
      "must_do_id": null,
      "note": "Pontocho after dark costs nothing to stroll, and the lanterns do the photography for you."
    }
